const inputRoot = $('Receive request').first().json;
const input = inputRoot.body ?? inputRoot;
const ai = $json;
const executionId = typeof $execution !== 'undefined' && $execution.id ? $execution.id : Date.now();
const requestId = input.request_id || input.live_probe?.request_id || `req_${executionId}`;
const query = input.input?.query || input.chatInput || input.message || 'Public-safe Actor Twin readiness probe.';
const aiText = ai.output || ai.text || ai.response || ai.message || '';

function parseEmbeddedJson(value) {
  const text = String(value || '').trim();
  if (!text) return null;
  const fenced = text.match(/```(?:json)?\s*([\s\S]*?)```/i);
  const candidate = (fenced ? fenced[1] : text).trim();
  if (!candidate.startsWith('{') || !candidate.endsWith('}')) return null;
  try { return JSON.parse(candidate); } catch { return null; }
}

const embedded = parseEmbeddedJson(aiText) || {};
const embeddedOutput = embedded.output && typeof embedded.output === 'object' ? embedded.output : embedded;
const explicit = input.context?.route_decision || input.output?.route_decision || embedded.output?.route_decision || embedded.route_decision || embeddedOutput.route_decision || null;
const decision = explicit?.decision || 'answer_direct';
const targetAgent = explicit?.target_agent || (decision === 'update_knowledge' ? 'knowledge_fabric_agent' : decision === 'activate_skill' || decision === 'create_skill' ? 'agentic_butler' : 'actor_twin');
const routeDecision = {
  decision,
  target_agent: targetAgent,
  intent: explicit?.intent || input.intent || embedded.intent || 'answer_question',
  visible_state: explicit?.visible_state || (decision === 'answer_direct' ? 'answering' : decision === 'update_knowledge' ? 'capturing_knowledge' : 'approval_required'),
  approval_required: Boolean(explicit?.approval_required || decision === 'create_skill'),
  handoff_required: Boolean(explicit?.handoff_required ?? targetAgent !== 'actor_twin'),
  reason: explicit?.reason || 'Actor Twin AI Agent response normalized into explicit route decision.'
};
const response = {
  envelope_version: input.envelope_version || '0.1.0',
  request_id: requestId,
  agent_id: 'actor_twin',
  status: routeDecision.approval_required ? 'approval_required' : 'completed',
  output: {
    answer: embeddedOutput.answer || aiText || `Actor Twin AI node completed but returned no text for query: ${query}`,
    route_decision: routeDecision,
    confidence: embeddedOutput.confidence || (aiText ? 0.78 : 0.58),
    mode: routeDecision.decision,
    citations: embeddedOutput.citations || [],
    handoff: { required: routeDecision.handoff_required, target_agent: routeDecision.target_agent },
    ai_agent: { integrated: true, node: 'Actor Twin AI Agent' }
  },
  trace: { stored: true, trace_id: `n8n_exec_${executionId}`, used_agents: ['actor_twin_ai_agent'], target_agent: routeDecision.target_agent, route_decision: routeDecision.decision, handoff_status: routeDecision.handoff_required ? 'route_decided' : 'not_required', ai_agent_integrated: true }
};
return [{ json: response }];

